%% Track2 demo: routes + multi-train operation
%% Seattle 1 Line with one bidirectional route and one train per physical track.

config
  dwell: 5s
end

trackgroup Line1
  north: [CAP-N] ---s1--- [WES-N] ---s2--- [SYM-N] ---s3--- [PIO-N] ---s4--- [IDC-N]
  south: [CAP-S] ---s5--- [WES-S] ---s6--- [SYM-S] ---s7--- [PIO-S] ---s8--- [IDC-S]
end

%% Green route: full line, 2 trains
route Green
  trackgroup: Line1
  color: green
  platforms: CAP, WES, SYM, PIO, IDC
  trains: 2
end
